console.log('Сюжет и визуальная новелла');
const DIRS = new Set(['bg', 'cg', 'fx', 'title', 'hide', 'choice', 'set', 'give', 'if', 'rec', 'loy', 'aff', 'date', 'bell']);
const walk = (lines, fn) => lines.forEach((l) => { fn(l); if (l[0] === 'choice') l[1].forEach((o) => walk(o.r || [], fn)); if (l[0] === 'if') walk(l[2], fn); });
const allScenes = () => Object.keys(D.SCENES).map((id) => [id, D.SCENES[id].lines]).concat(D.ROM_IDS.flatMap((id) => D.ROMANCE[id].scenes.map((sc, i) => [id + '#' + i, sc.lines])));
const BGS = new Set(['courtyard', 'street_fest', 'void', 'void_dusk', 'camp', 'ruins', 'forest', 'mines', 'swamp', 'spire', 'cathedral']);
t('все сцены: известные спикеры, настроения, директивы и фоны', () => { allScenes().forEach(([id, lines]) => walk(lines, (l) => { const k = l[0]; if (DIRS.has(k)) { if (k === 'bg') assert(BGS.has(l[1]), id + ' bg ' + l[1]); if (k === 'cg') assert(l[1] === null || MAN.cg['cg_' + l[1]], id + ' cg ' + l[1]); if (k === 'rec') assert(D.CREW[l[1]], id + ' rec ' + l[1]); if (k === 'loy' || k === 'aff') Object.keys(l[1]).forEach((c) => assert(D.CREW[c], id + ' ' + k + ' ' + c)); return; } assert(D.SPEAKERS[k], id + ' спикер ' + k); assert(typeof l[1] === 'string' && l[1].length, id); if (l[2]) assert('nhasdm'.includes(l[2]), id + ' настроение ' + l[2]); })); });
t('объём сюжета ≥ 6000 слов + романтика ≥ 1800 слов', () => { const wc = (lines) => { let n = 0; walk(lines, (l) => { if (!DIRS.has(l[0]) && typeof l[1] === 'string') n += l[1].split(/\s+/).length; }); return n; }; const story = Object.keys(D.SCENES).reduce((a, id) => a + wc(D.SCENES[id].lines), 0); const rom = D.ROM_IDS.reduce((a, id) => a + D.ROMANCE[id].scenes.reduce((b, sc) => b + wc(sc.lines), 0), 0); console.log('     слов сюжета:', story, ' романтики:', rom); assert(story >= 6000, String(story)); assert(rom >= 1800, String(rom)); });
t('D.STORY: порядок, каждая сцена существует, пре-сцена скрыта', () => { D.STORY.forEach((st) => assert(D.SCENES[st.id], st.id)); assert(D.STORY.some((s) => s.pre)); assert.strictEqual(D.STORY[0].id, 'prologue'); });
t('сюжет линейно открывается: пролог → ch1_a → вылазка → ch1_b …', () => { const s = mk(); assert.strictEqual(E.nextScene(s).id, 'prologue'); E.finishScene(s, 'prologue'); E.setFlags(s, { prologue_done: 1 }); const n = E.nextScene(s); assert.strictEqual(n.id, 'ch1_a'); E.finishScene(s, 'ch1_a'); const n2 = E.nextScene(s); assert(!n2 || n2.id !== 'ch1_b' || s.prog.cleared.mill, 'ch1_b требует Руины'); });
t('дуэли и пред-босс: сцены существуют и привязаны к врагам', () => { Object.keys(D.DUEL_SCENE).forEach((e) => { assert(D.ENEMIES[e] && D.ENEMIES[e].duel, e); assert(D.SCENES[D.DUEL_SCENE[e]], e); }); assert(D.SCENES[D.PRE_BOSS.cathedral]); assert(D.ENEMIES.lumiel && D.ENEMIES.lumiel.role === 'boss'); ['h_fiora', 'h_elvira', 'h_selestina'].forEach((e) => assert(D.DUEL_SCENE[e])); });
t('директивы сюжета: rec/loy/aff применяются через флаги и выдачу (E.recruit/addLoy)', () => { const s = mk(); const lines = []; walk(D.SCENES.ch1_a.lines, (l) => lines.push(l)); assert(lines.some((l) => l[0] === 'rec' && l[1] === 'gen1')); });
t('Кафедрал закрыт, пока не прочитана «У врат собора» (ch3_d)', () => { const s = mk(); s.story.flags.prologue_done = 1; s.prog.cleared.spire = 1; assert(!E.dungeonUnlocked(s, 'cathedral')); s.story.done.push('ch3_d'); assert(E.dungeonUnlocked(s, 'cathedral')); });
t('подземелья: 6 штук с новыми названиями', () => { assert.strictEqual(D.DUNGEONS.length, 15); assert.strictEqual(D.DUN.cathedral.n, 'Собор Пяти Богов'); assert.strictEqual(D.DUN.mill.n, 'Руины Хельмора'); });

console.log('Арт и настроения');
