console.log('Постановка VN: геометрия, вырезание, анимации (статические проверки)');
const PORTS = Object.keys(MAN.dim).filter((f) => !f.startsWith('cg_'));
t('у каждого портрета есть метрики лица [w,h,keyed,fx,fy,fw]; высота 720 (без синтетического продления)', () => PORTS.forEach((f) => { const d = MAN.dim[f]; assert(d.length >= 6, f + ' метрики'); assert.strictEqual(d[2], 1, f + ' keyed'); assert(d[1] >= 400 && (d[1] <= 720 || (d.length >= 10 && d[8] > 0 && d[8] <= d[1])), f + ' высота ' + d[1]); assert(d[3] > 0 && d[3] < d[0] && d[4] > 0 && d[4] < d[1], f + ' центр лица'); assert(d.length >= 8, f + ' смещение кадрирования'); assert(d[5] >= 90 && d[5] <= 520, f + ' ширина лица ' + d[5]); }));
t('60 портретов; файл = логический размер × fs (у героя fs в dim[9] — нативное разрешение 1:1), без растягивания', () => { assert(PORTS.length >= 60); assert(MAN.fs > 0.5 && MAN.fs <= 1); PORTS.forEach((f) => { const b = fs.readFileSync(path.join(__dirname, '../assets/vn', f)); assert(b.toString('latin1', 0, 4) === 'RIFF' && b.toString('latin1', 12, 16) === 'VP8X', f + ' webp+alpha'); const w = 1 + b.readUIntLE(24, 3), h = 1 + b.readUIntLE(27, 3), d = MAN.dim[f]; const k = d[9] || MAN.fs; assert(Math.abs(w - d[0] * k) <= 1.5 && Math.abs(h - d[1] * k) <= 1.5, f + ' ' + w + 'x' + h + ' vs ' + d.slice(0, 2)); }); });
t('вес assets/vn: портреты ≤ 6 МБ, каждый ≤ 140 КБ (герой — нативное разрешение, ≤ 300 КБ на эмоцию)', () => { let tot = 0; PORTS.forEach((f) => { const s = fs.statSync(path.join(__dirname, '../assets/vn', f)).size; tot += s; assert(s <= (/^hero_(demon_)?(neutral|angry|sad|smirk|shy|surprised)\.webp$/.test(f) ? 300 : 140) * 1024, f + ' ' + Math.round(s / 1024) + ' КБ'); }); assert(tot <= 6 * 1024 * 1024, 'сумма ' + Math.round(tot / 1024) + ' КБ'); });
const REFS = (ids) => ids.map((id) => RPG.artMetricsOf(MAN, id, 'n'));
t('vnLayout: одинаковый размер голов при 1/2/3 актёрах и на узком экране', () => { [[390, 716], [360, 500], [430, 800]].forEach(([W, Yb]) => [['hero'], ['hero', 'gen1'], ['hero', 'gen1', 'hero1'], ['gen9', 'sub_tik', 'apostle']].forEach((ids) => { const L = RPG.vnLayout(REFS(ids), W, Yb); assert.strictEqual(L.length, ids.length); const fw = L.map((g, i) => g.s * REFS(ids)[i].fw); assert(Math.max(...fw) - Math.min(...fw) < 0.5, 'головы разные: ' + fw.join(',')); })); });
t('vnLayout: слоты 0.5 / 0.28-0.72 / 0.17-0.5-0.83; лица на одной линии, голова не выше края, нижняя кромка у всех на линии диалога, масштаб равномерный', () => {
  [[390, 716], [444, 800], [360, 500]].forEach(([W, Yb]) => [['hero'], ['hero', 'gen1'], ['hero', 'gen1', 'hero1'], ['gen9', 'sub_tik', 'apostle'], ['sub_grak', 'hero', 'gen1']].forEach((ids) => { const refs = REFS(ids), L = RPG.vnLayout(refs, W, Yb), slots = RPG.VN.SLOTS[ids.length], V = RPG.VN, Yl = Yb + V.SINK * L[0].face / 240;
    L.forEach((g, i) => { const r = refs[i], cx = g.x + V.FR_CX * g.s, cy = g.y + (V.FR_T + r.fy) * g.s, bottom = g.y + g.frH * g.s; assert(Math.abs(cx - slots[i] * W) < 0.01, 'слот'); assert(Math.abs(cy - L[0].yf) < 0.01, 'лица на одной линии ' + ids.join('+')); assert(cy - 0.7 * r.fw * g.s > 0, 'голова ниже верха ' + ids.join('+')); assert(Math.abs(bottom - Yl) < 0.01, 'низ кадра на линии диалога'); assert(g.frH <= V.FR_T + (r.vh || r.h) + 0.01 && bottom > Yb, 'кадр не длиннее файла'); }); })); });
t('герой: портрет до пояса (кадр не выше 3.3 лица ниже центра лица), vnLayout без неравномерного масштаба: один s на оба измерения', () => { ['hero', 'hero_demon'].forEach((form) => ['n', 'a', 'h', 'd', 's', 'u'].forEach((mn) => { const m = RPG.artMetricsOf(MAN, 'hero', form === 'hero' ? mn : 'm' + (mn === 'n' ? '' : mn)); assert(m.img && (m.vh - m.fy) / m.fw >= 2.5 && (m.vh - m.fy) / m.fw <= 3.3, form + mn + ' до пояса: ' + ((m.vh - m.fy) / m.fw).toFixed(2)); })); const L = RPG.vnLayout([RPG.artMetricsOf(MAN, 'hero', 'n')], 444, 800)[0]; assert(L.s > 0 && typeof L.s === 'number' && !('sy' in L)); });
t('vnPlaceRect: лица всех настроений персонажа совпадают с эталоном (центр и ширина)', () => { Object.keys(MAN.portraits).forEach((id) => { const ref = RPG.artMetricsOf(MAN, id, 'n'); Object.keys(MAN.portraits[id]).forEach((mn) => { const f = MAN.portraits[id][mn], d = MAN.dim[f], m = { w: d[0], h: d[1], fx: d[3], fy: d[4], fw: d[5] }, p = RPG.vnPlaceRect(ref, m); assert(Math.abs(p.left + m.fx * p.r - RPG.VN.FR_CX) < 0.01, id + mn + ' x'); assert(Math.abs(p.top + m.fy * p.r - (RPG.VN.FR_T + ref.fy)) < 0.01, id + mn + ' y'); assert(Math.abs(m.fw * p.r - ref.fw) < 0.01, id + mn + ' размер'); }); }); });
t('масштабы настроений одного персонажа в разумных пределах (0.5–2): лицо нигде не найдено «не там»', () => { Object.keys(MAN.portraits).forEach((id) => { const ref = RPG.artMetricsOf(MAN, id, 'n'); Object.keys(MAN.portraits[id]).forEach((mn) => { const m = RPG.artMetricsOf(MAN, id, { neutral: 'n', happy: 'h', angry: 'a', shy: 's', sad: 'd', smirk: 'h', despair: 'd', demon: 'm' }[mn]); const r = ref.fw / m.fw; assert(r > 0.5 && r < 2, id + '_' + mn + ' r=' + r.toFixed(2)); }); }); });
const CSS_VN = fs.readFileSync(path.join(__dirname, '../css/vn.css'), 'utf8'), CSS_ALL = fs.readFileSync(path.join(__dirname, '../css/style.css'), 'utf8'), JS_VN = fs.readFileSync(path.join(__dirname, '../js/ui-vn.js'), 'utf8'), JS_PLAY = fs.readFileSync(path.join(__dirname, '../js/ui-play.js'), 'utf8');
t('анимации: позиция актёра (transform) не конфликтует с анимациями — у .vact нет keyframes-анимаций, дыхание/поп на вложенных слоях', () => { assert(!/\.vact\s*\{[^}]*animation:/.test(CSS_VN)); assert(/\.vbr\s*\{[^}]*animation:breathe/.test(CSS_VN)); assert(/\.vpp\.pop\s*\{animation:vpop/.test(CSS_VN)); });
t('анимации: дыхание на паузе у неговорящих (без скачка при смене роли)', () => assert(/animation-play-state:paused/.test(CSS_VN) && /\.vact\.talk \.vbr\s*\{animation-play-state:running/.test(CSS_VN)));
t('анимации: halo/flash не залипают — у псевдоэлемента halo базовая opacity:0 и fill both', () => { const m = CSS_VN.match(/\.story\.halo::after\{[^}]*\}/); assert(m && /opacity:0/.test(m[0]) && /animation:fl 1\.6s both/.test(m[0])); });
t('reduced-motion: нет «0.01s в цикле» (мерцание), анимации отключены', () => { const m = CSS_ALL.match(/@media \(prefers-reduced-motion:reduce\)\{[\s\S]*?\n\}/); assert(m, 'блок есть'); assert(/animation:none!important/.test(m[0]) && !/\.0*1s|animation-duration/.test(m[0]), 'без 0.01s'); assert(!/transform/.test(m[0].split('transition-property')[1].split(';')[0]), 'transform не анимируется'); });
t('бой: renderUnits не стирает hit/acting (syncCls), hit/acting не конфликтуют по transform', () => { assert(/function syncCls/.test(JS_PLAY) && !/old\.className = nw\.className/.test(JS_PLAY.replace(/function syncCls[^\n]*/, ''))); assert(/\.unit\.hit\{animation:hit/.test(CSS_ALL) && /@keyframes hit\{25%\{translate:/.test(CSS_ALL) && /\.unit\.acting\{scale:/.test(CSS_ALL)); });
t('плеер: гонка фонов (finalizeBg/bgGen), таймеры эффектов снимаются, resize-слушатель удаляется', () => { assert(/finalizeBg/.test(JS_VN) && /bgGen/.test(JS_VN)); assert(/removeEventListener\('resize', onResize\)/.test(JS_VN) && /timers\.forEach\(clearTimeout\)/.test(JS_VN)); assert(!/setTimeout\(\(\) => root\.classList\.remove/.test(JS_VN)); });
t('постановка: тень/свечение, rim-light по сцене, маска затухания снизу, параллакс фона', () => { assert(!/drop-shadow/.test(CSS_VN), 'без drop-shadow на больших слоях'); assert(!/vfloor/.test(CSS_VN + JS_VN), 'нет тёмного блока .vfloor'); assert(/\.vact::before\{[^}]*rgba\(var\(--rim\)/.test(CSS_VN)); assert(/\.vimgs\{[^}]*mask-image:linear-gradient/.test(CSS_VN)); assert(/@keyframes bgdrift/.test(CSS_VN) && /@keyframes sildrift/.test(CSS_VN)); assert(/\.vact::before/.test(CSS_VN)); });
t('sw.js: версия ≥ 2.0.1', () => { const sw = fs.readFileSync(path.join(__dirname, '../sw.js'), 'utf8'); const v = sw.match(/VERSION = 'arpg-v(\d+)\.(\d+)\.(\d+)'/); assert(v); assert(+v[1] > 2 || (+v[1] === 2 && (+v[2] > 0 || +v[3] >= 1))); });
t('мобильное мерцание: нет filter на больших слоях; затемнение — лёгкий filter только на самой картинке; у анимируемых слоёв (.vact/.vpp/.vbr/.vbg) filter нет', () => { const rule = (sel) => (CSS_VN.match(new RegExp('(?:^|[}\\n])\\s*' + sel.replace(/\./g, '\\.') + '\\s*\\{[^}]*\\}', 'g')) || []).join(''); assert(!/filter:/.test(rule('.vslide')), '.vslide без filter'); assert(/\.vimgs \.vsp\{filter:brightness/.test(CSS_VN)); ['.vact', '.vpp', '.vbr', '.vslide', '.vimgs', '.vbg'].forEach((s) => assert(!/(^|[;{])filter:/.test(rule(s)), s + ' без filter')); assert(!/\.vbr[^{]*\{[^}]*filter/.test(CSS_VN)); });
t('мобильное мерцание: дыхание/параллакс/Ken-Burns медленные (6–40 с), ease-in-out, без steps', () => { [['breathe', 6, 12], ['bgdrift', 6, 40], ['sildrift', 6, 40], ['kb', 6, 40]].forEach(([n, lo, hi]) => { const m = CSS_VN.match(new RegExp('animation:' + n + ' ([\\d.]+)s ([\\w-]+)')); assert(m, n); assert(+m[1] >= lo && +m[1] <= hi, n + ' длительность ' + m[1]); assert(m[2] === 'ease-in-out', n + ' easing'); }); assert(!/steps\(/.test(CSS_VN)); });
t('мобильное мерцание: reduced-motion — animation:none и без transform в transition-property, 0.01s нет нигде', () => { assert(!/animation-duration:\s*\.0*1s/.test(CSS_ALL + CSS_VN)); const m = CSS_ALL.match(/prefers-reduced-motion:reduce\)\{[\s\S]*?\n\}/)[0]; assert(/animation:none!important/.test(m)); assert(!/transform|translate|scale/.test(m.match(/transition-property:([^;]*);/)[1])); });
t('мобильное мерцание: resize-слушатель VN сглажен через rAF и отключает transition (адресная строка Android), холст частиц не пересоздаётся без смены размера', () => { assert(/requestAnimationFrame\(\(\) => \{ if \(finished\)/.test(JS_VN) && /nofx/.test(JS_VN) && /\.vstage\.nofx \.vact\{transition:opacity/.test(CSS_VN)); const fx = fs.readFileSync(path.join(__dirname, '../js/fx.js'), 'utf8'); assert(/F\.cv\.width === Math\.round\(w \* d\)/.test(fx) && /const k = dt \/ 16\.7/.test(fx)); });
t('мобильное мерцание: позиция актёра округляется до 0.5 px', () => assert(/Math\.round\(g\.x \* 2\) \/ 2/.test(JS_VN)));
t('лаги VN: пул декодированных картинок, look-ahead по репликам, показ после decode', () => { assert(/UI\.imgPool/.test(JS_VN) && /UI\.prefetch/.test(JS_VN) && /const ahead = \(n\)/.test(JS_VN) && /ahead\(3\)/.test(JS_VN) && /decode\(\)/.test(JS_VN)); });
t('лаги VN: кроссфейд настроений — не более 3 слоёв, ожидающие decode выбрасываются, старые слои снимаются по таймеру', () => { assert(/box\.children\.length > 2/.test(JS_VN) && /nw\.previousElementSibling\.remove/.test(JS_VN) && /classList\.contains\('on'\)\) c\.remove/.test(JS_VN)); });

console.log('Этап 2: характеристики');
t('8 основных характеристик, русские названия, 5 очков за уровень', () => { assert.deepStrictEqual(D.STATS, ['str', 'agi', 'vit', 'int', 'spi', 'wis', 'luk', 'cha']); ['Сила', 'Ловкость', 'Выносливость', 'Интеллект', 'Воля', 'Мудрость', 'Удача', 'Харизма'].forEach((n, i) => assert.strictEqual(D.STAT_N[D.STATS[i]], n)); assert.strictEqual(D.STAT_PER_LEVEL, 5); D.CLASS_IDS.forEach((c) => { const d = E.derive(mk(c)); D.STATS.forEach((k) => assert(d[k] > 0, c + ' ' + k)); }); });
t('очки характеристик: уровень 1 → 0, ур. 10 → 45; черновик применяется целиком, лишнее отвергается', () => { const s = mk(); assert.strictEqual(E.statFree(s.hero), 0); s.hero.level = 10; assert.strictEqual(E.statFree(s.hero), 45); assert.strictEqual(E.statCommit(s, { str: 46 }), 0); assert.strictEqual(E.statCommit(s, { zzz: 1 }), 0); assert.strictEqual(E.statCommit(s, { str: -1 }), 0); const s0 = E.derive(s).str; assert.strictEqual(E.statCommit(s, { str: 20, luk: 5 }), 25); assert.strictEqual(E.derive(s).str, s0 + 20); assert.strictEqual(E.statFree(s.hero), 20); });
t('сброс очков за золото: цена растёт с уровнем, золото списывается', () => { const s = mk(); s.hero.level = 20; E.statCommit(s, { agi: 10 }); const c = E.statRespecCost(s.hero); assert(c > 0); s.gold = c - 1; assert.strictEqual(E.statRespec(s), false); s.gold = c + 5; assert.strictEqual(E.statRespec(s), true); assert.strictEqual(s.gold, 5); assert.strictEqual(E.statSpent(s.hero), 0); assert.strictEqual(E.statFree(s.hero), 95); });
t('субстаты: все 20+ на месте, значения в пределах cap, крит растёт с Удачей, разбивка источников сходится', () => { assert(D.SUBS.length >= 21); const s = mk(); s.hero.level = 40; const a = E.derive(s); D.SUBS.forEach((def) => { const v = a.sub[def.id]; assert(Number.isFinite(v) && v >= def.cap[0] && v <= def.cap[1], def.id + '=' + v); }); E.statCommit(s, { luk: 150 }); const b = E.derive(s); assert(b.sub.crit > a.sub.crit && b.sub.drop >= a.sub.drop); const rows = E.subRows(s); assert.strictEqual(rows.length, D.SUBS.length); rows.forEach((r) => { assert(r.formula && r.parts); if (r.raw < r.cap[1] && r.raw > r.cap[0]) assert(Math.abs(r.raw - r.v) < 0.5, r.id + ' ' + r.raw + ' vs ' + r.v); }); });
t('стихии: 9 стихий + физика, сопротивление ≤ 75%, Пустота зовётся Энтропией', () => { const s = mk(); const rows = E.elemRows(s); assert.strictEqual(rows.length, 10); ['fire', 'ice', 'bolt', 'earth', 'wind', 'water', 'light', 'dark', 'arcane', 'phys'].forEach((e) => assert(rows.find((r) => r.id === e), e)); assert(/Пустота|Энтроп/.test(D.ELEMS.arcane.n)); s.hero.level = 100; E.statCommit(s, { spi: 495 }); E.elemRows(s).forEach((r) => assert(r.res <= 75 && r.res >= -50)); });
t('миграция v4 → v5: прогресс цел, alloc создан', () => { const p = S.migrate(JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures/v3.json'), 'utf8'))); p.v = 4; const sl = p.slots[0]; delete sl.hero.alloc; sl.hero.level = 7; sl.gold = 123; const q = S.migrate(JSON.parse(JSON.stringify(p))); assert.strictEqual(q.v, 5); assert.deepStrictEqual(q.slots[0].hero.alloc, {}); assert.strictEqual(q.slots[0].hero.level, 7); assert.strictEqual(q.slots[0].gold, 123); assert(S.validate(q)); });
t('кап уровня 100, кривая опыта конечна и монотонна, мягкий рост', () => { assert.strictEqual(D.LEVEL_CAP, 100); let prev = 0; for (let l = 1; l < 100; l++) { const x = D.xpNeed(l); assert(Number.isFinite(x) && x > prev, 'xp ' + l); prev = x; } assert(D.xpNeed(99) / D.xpNeed(98) < 1.12); const s = mk(); E.addXp(s, 1e12); assert.strictEqual(s.hero.level, 100); });
t('враги: стихии (Церковь — свет, нежить — тьма), все навыки существуют, враги до ур. 100+', () => { let holy = 0, dark = 0; Object.keys(D.ENEMIES).forEach((id) => { const e = D.ENEMIES[id]; e.sk.forEach((k) => assert(D.ESK[k] || D.SKILLS[k], id + ' ' + k)); if (e.el === 'light') holy++; if (e.el === 'dark') dark++; }); assert(holy >= 5 && dark >= 8); const u = C.unitFromEnemy('gatekeeper', 130, 5, false, 'e0'); assert(u.maxHp > 0 && Number.isFinite(u.maxHp) && u.lv <= D.ENEMY_LV_CAP); });
t('бой: блок режет физический урон, двойной удар бьёт вдвое, точность съедает уклонение', () => { const hit = (mod) => { const s = mk('warrior'); s.hero.level = 10; const P = C.unitFromSlot(s), Tg = C.unitFromEnemy('rat', 10, 0, false, 'e0'); Tg.def = 0; Tg.eva = 0; Tg.hp = Tg.maxHp = 1e6; mod(P, Tg); const B = C.create([P], [Tg], E.rng(5), {}); P.spd = 999; const u = np(B, P); const hp0 = Tg.hp; C.act(B, u, { t: 'basic', tid: Tg.id }); return { B, d: hp0 - Tg.hp }; }; const base = hit(() => {}); const blk = hit((P, T) => { T.sub = Object.assign({}, T.sub, { blockCh: 100, blockPow: 50 }); }); assert(blk.B.ev.some((e) => e.s === 'Блок!')); assert(blk.d < base.d * 0.75, blk.d + ' vs ' + base.d); const dbl = hit((P) => { P.sub = Object.assign({}, P.sub, { dbl: 100 }); }); assert(dbl.B.ev.some((e) => e.s === 'Двойной удар!')); assert(dbl.d > base.d * 1.3); const ev1 = hit((P, T) => { T.eva = 70; P.sub = Object.assign({}, P.sub, { acc: 80 }); }); assert(!ev1.B.ev.some((e) => e.t === 'miss')); });
t('бой: вампиризм и закон «без крита» работают, крит у героя считается из субстатов', () => { const s = mk('rogue'); s.hero.level = 15; const d = E.derive(s); assert.strictEqual(d.crit, d.sub.crit); assert(Math.abs(d.critDmg - d.sub.critDmg / 100) < 1e-9); const P = C.unitFromSlot(s); assert(P.sub && P.sub.resEl); });
t('E.fmtBig: 1.2M, 3.4B, безопасно для NaN/∞', () => { assert.strictEqual(E.fmtBig(1234567), '1.2M'); assert.strictEqual(E.fmtBig(999), '999'); assert.strictEqual(E.fmtBig(NaN), '0'); assert(typeof E.fmtBig(Infinity) === 'string'); });

console.log('Этап 3: древо Силы, концепты, эффекты');
const tH = (lv, nodes, foes, seed) => { const s = mk(); s.hero.level = lv; s.hero.spent = {}; (nodes || []).forEach((id) => { s.hero.spent[id] = D.NODE_BY_ID[id].max; }); const P = C.unitFromSlot(s); P.spd = 12; const F = (foes || [['rat', lv]]).map((f, i) => { const e = C.unitFromEnemy(f[0], f[1], 0, false, 'e' + i); e.spd = 10; e.hp = e.maxHp = f[2] || 1e7; return e; }); const B = C.create([P], F, E.rng(seed || 3), {}); P.gauge = 100; return { s, P, F, B }; };
const heroTurn = (B, P) => { for (let i = 0; i < 80; i++) { const u = C.next(B); if (u === P) return P; if (B.over) return null; } return null; };
const castC = (B, P, id, tid) => { heroTurn(B, P); P.mp = P.maxMp; P.rc = P.rcMax; delete P.cds[id]; if (!P.sk.includes(id)) P.sk.push(id); return C.act(B, P, { t: 'skill', id, tid }); };
t('древо: связи существуют, ярусы по возрастанию, уровни до 100, все навыки и моды описаны', () => { const ids = new Set(T.nodes.map((n) => n.id)); assert.strictEqual(ids.size, T.nodes.length); T.nodes.forEach((n) => { n.req.forEach((q) => { assert(ids.has(q), n.id + '<-' + q); assert(D.NODE_BY_ID[q].lv <= n.lv && D.NODE_BY_ID[q].t <= n.t, n.id + ' порядок'); }); if (n.e.unlock) assert(D.SKILLS[n.e.unlock], n.id + ' навык ' + n.e.unlock); if (n.e.m) Object.keys(n.e.m).forEach((k) => assert(D.MODN[k] || D.MODN[k.replace(/^dmg_|^res_/, 'dmg_')] || /^(dmg|res)_/.test(k), 'MODN ' + k)); if (n.rr) Object.keys(n.rr).forEach((q) => assert(ids.has(q))); if (n.fuse) n.fuse.forEach((q) => assert(ids.has(q))); }); assert.strictEqual(Math.max(...T.nodes.map((n) => n.lv)), 100); });
t('древо: любой узел достижим из корня ветки, на ур. 100 хватает очков на большой билд, но не на всё', () => { let total = 0; T.nodes.forEach((n) => { total += n.max; const seen = new Set(); const up = (id) => { if (seen.has(id)) return; seen.add(id); D.NODE_BY_ID[id].req.forEach(up); }; up(n.id); assert([...seen].some((q) => !D.NODE_BY_ID[q].req.length), n.id); }); const s = mk(); s.hero.level = 100; assert(E.sp(s.hero) >= 200 && E.sp(s.hero) < total / 2, E.sp(s.hero) + ' vs ' + total); });
t('концептуальные навыки: ≥ 20 новых, у всех русское описание и лор, 25+ узлов-концептов', () => { const cs = Object.keys(D.SKILLS).filter((k) => /^c_/.test(k)); assert(cs.length >= 20, String(cs.length)); cs.forEach((k) => assert(D.SKILLS[k].conc && /[а-я]/.test(D.SKILLS[k].d) && D.SKILLS[k].n, k)); assert(D.CONCEPT_NODES.length >= 28, String(D.CONCEPT_NODES.length)); D.CONCEPT_NODES.forEach((id) => { const n = D.NODE_BY_ID[id]; assert(n.d && n.lore, id + ' нет описания/лора'); }); ['Мантра Силы', 'Стирание', 'Пожирание', 'Подчинение', 'Закон Короля', 'Остановка времени', 'Обращение урона', 'Бессмертие до конца хода', 'Вторая жизнь', 'Приказ мира'].forEach((nm) => assert(T.nodes.some((n) => n.n === nm), nm)); });
t('концепты открываются на высоких уровнях (20…100) и есть Преображения имба-навыков', () => { const lv = D.CONCEPT_NODES.map((id) => D.NODE_BY_ID[id].lv); [30, 40, 50, 60, 70, 80, 100].forEach((x) => assert(lv.some((v) => v >= x && v <= x + 9), 'ур. ' + x)); const tf = T.nodes.filter((n) => n.fuse && n.concept && n.rr); assert(tf.length >= 3); tf.forEach((n) => { const s = mk(); s.hero.level = 100; const old = D.NODE_BY_ID[n.fuse[0]]; assert(E.canLearn(s.hero, n.id)); s.hero.spent = {}; for (const q in n.rr) s.hero.spent[q] = n.rr[q] - 1; assert(/ранг/.test(E.canLearn(s.hero, n.id)), n.id); }); });
t('Преображение: «Распад бытия» → «Стирание» отключает старый навык, включает новый', () => { const s = mk(); s.hero.level = 100; const chain = ['E1', 'E2', 'E3', 'E4']; chain.forEach((q) => { s.hero.spent[q] = 1; }); s.hero.spent.E17 = 3; assert(E.skillsOf(s.hero).includes('k_unmake')); ['E6', 'E7', 'E5', 'E8'].forEach((q) => { s.hero.spent[q] = 1; }); ['E12', 'E9', 'E10', 'E11', 'E18'].forEach((q) => { s.hero.spent[q] = 1; }); s.hero.spent.E20 = 1; s.hero.spent.E23 = 1; s.hero.spent.E25 = 1; const ids = E.skillsOf(s.hero); assert(ids.includes('c_erase') && !ids.includes('k_unmake')); });
t('пассивки мощные: дерево даёт ≥ ×2 к урону при разумном билде на 100-м уровне', () => { const s = mk(); s.hero.level = 100; const d0 = E.derive(s); const top = ['R25', 'R29', 'R31', 'R34', 'P29', 'D29', 'E29', 'C27', 'B27', 'T25', 'M27']; top.forEach((id) => { s.hero.spent[id] = D.NODE_BY_ID[id].max; }); const d1 = E.derive(s); assert(d1.mods.dmgMul >= 100, 'dmgMul ' + d1.mods.dmgMul); assert(d1.atk > d0.atk * 1.2); assert(d1.critDmg > d0.critDmg + 0.4); assert((d1.mods.lifesteal || 0) >= 8); });
t('масштабирование от уровня и характеристик: dmgPerWil/dmgPerInt/dmgPerLv растут с Волей, Интеллектом и уровнем', () => { const mkS = (lv, alloc) => { const s = mk(); s.hero.level = lv; s.hero.spent = { R20: 3, R21: 3, R23: 3 }; if (alloc) s.hero.alloc = alloc; return E.derive(s).mods.dmg; }; assert(mkS(60, { spi: 100 }) > mkS(60) + 5); assert(mkS(100) > mkS(40)); assert(mkS(60, { int: 100 }) > mkS(60)); });
t('dmgMul перемножается, killStack/growDmg/foeDmg усиливают урон', () => { const hit = (mods, setupFn) => { const { P, F, B } = tH(20, [], [['rat', 20], ['bat', 20]]); Object.assign(P.mods, mods); P.crit = 0; F.forEach((e) => { e.def = 0; e.eva = 0; }); if (setupFn) setupFn(P, F, B); heroTurn(B, P); const hp = F[0].hp; C.act(B, P, { t: 'basic', tid: F[0].id }); return hp - F[0].hp; }; const base = hit({}); assert(hit({ dmgMul: 100 }) > base * 1.7); assert(hit({ killStack: 10 }, (P) => { P.kills = 5; }) > base * 1.3); assert(hit({ growDmg: 10 }, (P) => { P.turns = 9; }) > base * 1.5); assert(hit({ foeDmg: 20 }) > base * 1.25); });
t('c_stop: враги (даже босс) пропускают ход, Король ходит снова', () => { const { P, F, B } = tH(60, [], [['rat', 60], ['gatekeeper', 60]]); F[1].role = 'boss'; castC(B, P, 'c_stop'); assert(F.every((f) => f.st.some((x) => x.id === 'stop'))); assert(P.gauge >= 100, 'лишний ход ' + P.gauge); const u = C.next(B); assert.strictEqual(u, P); assert(!F.some((f) => f.hp < f.maxHp), 'враги не ходили'); });
t('c_law: враги без критов, контроля, лечения и призыва; закон истекает', () => { const { P, F, B } = tH(60, [], [['rat', 60]]); castC(B, P, 'c_law'); assert(B.law.nocrit > 0 && B.law.noctrl > 0 && B.law.noheal > 0 && B.law.nosummon > 0); const e = F[0]; e.crit = 100; e.atk = 50; P.eva = 0; P.def = 0; for (let i = 0; i < 6; i++) { const hp0 = P.hp; B.cur = e; B.units.forEach((u) => { u.gauge = 0; }); e.gauge = 100; B.cur = null; const x = C.next(B); if (x === P) C.act(B, P, { t: 'guard' }); } assert(!B.ev.some((q) => q.t === 'dmg' && q.from === e.id && q.crit), 'крит врага запрещён'); for (let i = 0; i < 12 && B.law.nocrit > 0; i++) { const x = C.next(B); if (x === P) C.act(B, P, { t: 'guard' }); } assert(!B.law.nocrit, 'закон закончился'); });
t('c_erase: слабого стирает мгновенно, босса — лишь 12% здоровья, здорового — урон', () => { const { P, F, B } = tH(70, [], [['rat', 70], ['rat', 70], ['gatekeeper', 70]]); F[0].hp = Math.round(F[0].maxHp * 0.3); F[2].role = 'boss'; castC(B, P, 'c_erase', F[0].id); assert(!F[0].alive, 'стёрт'); P.cds.c_erase = 0; castC(B, P, 'c_erase', F[1].id); assert(F[1].alive && F[1].hp < F[1].maxHp, 'здоровый — просто урон'); P.cds.c_erase = 0; const h0 = F[2].hp; castC(B, P, 'c_erase', F[2].id); assert(F[2].alive && h0 - F[2].hp <= F[2].maxHp * 0.121 + 1, 'босс'); });
t('c_devour: пожирает слабого, лечит, копит бонус урона', () => { const { P, F, B } = tH(60, [], [['rat', 60], ['rat', 60]]); F[0].hp = Math.round(F[0].maxHp * 0.2); P.hp = Math.round(P.maxHp * 0.4); castC(B, P, 'c_devour', F[0].id); assert(!F[0].alive && P.devStack === 1 && P.hp > P.maxHp * 0.6, P.hp + '/' + P.maxHp); });
t('c_thrall: подчинённый враг 3 хода бьёт своих; боссы могут сопротивляться', () => { const { P, F, B } = tH(60, [], [['rat', 60], ['bat', 60]]); castC(B, P, 'c_thrall', F[0].id); assert(F[0].st.some((x) => x.id === 'dominate' && x.dur === 3)); let hits = 0; for (let i = 0; i < 12; i++) { const x = C.next(B); if (x === P) C.act(B, P, { t: 'guard' }); } assert(F[1].hp < F[1].maxHp, 'союзник получил урон от подчинённого'); });
t('c_mirror: часть урона не доходит до героя, а возвращается врагу', () => { const { P, F, B } = tH(60, [], [['rat', 60]]); castC(B, P, 'c_mirror'); const e = F[0], hp0 = e.hp; e.crit = 0; e.gauge = 100; P.gauge = 0; P.eva = 0; P.sub.statRes = 0; const r = C.has(P, 'reflect'); assert(r && r.pow === 0.6); P.hp = P.maxHp; const php = P.hp; for (let i = 0; i < 10 && P.hp === php; i++) { const x = C.next(B); if (x === P) C.act(B, P, { t: 'guard' }); } assert(e.hp < hp0, 'отражено'); });
t('c_immortal: цена 25% HP, один раз за бой, HP не падает ниже 1, расплата по окончании', () => { const { P, F, B } = tH(60, [], [['rat', 60]]); const m = P.maxHp; castC(B, P, 'c_immortal'); assert(P.hp <= m * 0.76, 'цена'); assert(P.cds.c_immortal >= 99, 'один раз'); P.hp = 5; F[0].atk = 1e6; let guard = 0; while (C.has(P, 'immortal') && guard++ < 20) { const x = C.next(B); if (x === P) { C.act(B, P, { t: 'guard' }); } } assert(P.immDebt >= 0); assert(guard > 0); });
t('Вторая жизнь: раз за бой возвращает 65% HP и даёт бессмертие на 2 хода', () => { const { P, F, B } = tH(60, ['P33'], [['rat', 60]]); assert(P.mods.secondLife >= 2); P.hp = 3; P.mods.reviveFull = 0; P.eva = 0; F[0].gauge = 100; P.gauge = 0; F[0].eva = 0; for (let i = 0; i < 6 && !B.over; i++) { const x = C.next(B); if (x === P) C.act(B, P, { t: 'guard' }); if (P.slUsed) break; } assert(P.slUsed && P.alive && P.hp >= 1 && B.ev.some((q) => q.t === 'revive') && (C.has(P, 'immortal') || P.hp > 1)); });
t('c_decree: шкала хода врагов отброшена, они уязвимы и ослаблены', () => { const { P, F, B } = tH(70, [], [['rat', 70], ['bat', 70]]); F.forEach((f) => { f.gauge = 80; }); castC(B, P, 'c_decree'); F.forEach((f) => { assert(f.gauge <= -60 + 1e-6 || f.gauge < 0, 'gauge ' + f.gauge); assert(C.has(f, 'vuln') && C.has(f, 'weak')); }); });
t('c_silence: враги только бьют обычным ударом на 3 хода', () => { const { P, F, B } = tH(40, [], [['gatekeeper', 40]]); castC(B, P, 'c_silence'); assert(B.law.nocast > 0); for (let i = 0; i < 6; i++) { const x = C.next(B); if (x === P) C.act(B, P, { t: 'guard' }); } const sk = B.ev.filter((q) => q.t === 'skill' && q.tg && q.tg.length && q.u === F[0].id); assert(sk.every((q) => q.id === 'basic' || q.n === 'Удар'), JSON.stringify(sk.slice(0, 3))); });
t('c_echo: повторяет последний навык бесплатно и слабее', () => { const { P, F, B } = tH(60, [], [['rat', 60]]); F[0].def = 0; F[0].eva = 0; P.crit = 0; castC(B, P, 'k_smite', F[0].id); const d1 = F[0].maxHp - F[0].hp; P.cds.c_echo = 0; heroTurn(B, P); const mp0 = P.mp = P.maxMp; const hp1 = F[0].hp; C.act(B, P, { t: 'skill', id: 'c_echo' }); const d2 = hp1 - F[0].hp; assert(d2 > 0 && d2 < d1 * 1.2, d1 + ' / ' + d2); assert(P.mp >= mp0 - C.mpCost(P, D.SKILLS.c_echo) - 1, 'эхо бесплатно'); });
t('c_eye + markCrit: удар по меченому всегда критический', () => { const { P, F, B } = tH(60, ['B19'], [['rat', 60]]); assert(P.mods.markCrit > 0); P.crit = 0; F[0].eva = 0; castC(B, P, 'c_eye', F[0].id); assert(B.ev.filter((q) => q.t === 'dmg' && q.from === P.id).every((q) => q.crit)); });
t('c_pact: цена здоровья, +80% урона, возврат здоровья', () => { const { P, F, B } = tH(60, [], [['rat', 60]]); const m = P.maxHp; castC(B, P, 'c_pact'); assert(P.hp <= m * 0.71 && C.has(P, 'pact')); const hp = P.hp; heroTurn(B, P); C.act(B, P, { t: 'basic', tid: F[0].id }); assert(P.hp > hp, 'вампиризм договора'); });
t('c_blades: 12 ударов; c_sever снимает баффы и раскалывает броню', () => { const { P, F, B } = tH(60, [], [['rat', 60], ['bat', 60]]); F[0].eva = F[1].eva = 0; P.sub.dbl = 0; castC(B, P, 'c_blades'); assert.strictEqual(B.ev.filter((q) => q.t === 'dmg' && q.from === P.id).length, 12); C.addSt(B, P, F[0], 'haste', 3); C.addSt(B, P, F[0], 'shield', 3, 99); castC(B, P, 'c_sever'); F.forEach((f) => assert(C.has(f, 'sunder'))); assert(!C.has(F[0], 'haste') && !C.has(F[0], 'shield')); });
t('Присутствие Тирана: враги слабее с первой секунды и отброшены назад по шкале', () => { const { s, P, F, B } = tH(60, [], [['rat', 60]]); const s2 = mk(); s2.hero.level = 60; s2.hero.spent = { T21: 2 }; const P2 = C.unitFromSlot(s2); const e = C.unitFromEnemy('rat', 60, 0, false, 'e0'); const g0 = e.gauge; const B2 = C.create([P2], [e], E.rng(1), {}); assert(C.has(e, 'tyrant')); assert(e.gauge < 20, 'gauge ' + e.gauge); });
t('Мантры: Мантра Разума удваивает магию и сопротивление, Мантра Мгновения ускоряет, предел ограничен', () => { const { P, F, B } = tH(60, ['M24', 'M26'], [['rat', 60]]); const mag0 = P.mag, res0 = P.res, spd0 = P.spd; for (let i = 0; i < 6; i++) { heroTurn(B, P); C.act(B, P, { t: 'guard' }); } assert.strictEqual(P.mgs, 3); assert(Math.abs(P.mag - mag0 * 8) < 1, P.mag + ' vs ' + mag0 * 8); assert(P.res >= res0 * 8 - 1); const { P: P2, B: B2 } = tH(60, [], [['rat', 60]]); assert(!P2.m0); const sP = mk(); sP.hero.level = 60; sP.hero.spent = { P14: 1, P15: 2, P10: 3, P12: 3 }; const U = C.unitFromSlot(sP); assert(U.mods.mantra > 0); });
t('Мантра Силы сохранена: удваивает атаку и броню каждый ход, значения считаются от значений ДО боя', () => { const sP = mk(); sP.hero.level = 40; sP.hero.spent = { P14: 1 }; const e = C.unitFromEnemy('rat', 5, 0, false, 'e0'); e.hp = e.maxHp = 1e9; e.spd = 1; const U = C.unitFromSlot(sP); U.spd = 40; const atk0 = U.atk, def0 = U.def; const B = C.create([U], [e], E.rng(2), {}); U.gauge = 100; for (let i = 0; i < 3; i++) { heroTurn(B, U); C.act(B, U, { t: 'guard' }); } assert(U.mst >= 3 && U.mods.mantra >= 3); assert(Math.abs(U.atk - atk0 * Math.pow(2, U.mst)) < 1); assert(Math.abs(U.def - def0 * Math.pow(2, U.mst)) < 1); const U2 = C.unitFromSlot(sP); assert(Math.abs(U2.atk - atk0) < 1, 'после боя значения прежние'); });
t('безопасные числа: билд на максимум не даёт NaN/Infinity, урон ограничен, fmtBig форматирует', () => { const s = mk(); s.hero.level = 100; T.nodes.forEach((n) => { s.hero.spent[n.id] = n.max; }); s.hero.alloc = { str: 495 }; const d = E.derive(s); ['maxHp', 'maxMp', 'atk', 'mag', 'def', 'res', 'spd', 'crit', 'critDmg', 'eva'].forEach((k) => assert(Number.isFinite(d[k]), k)); const P = C.unitFromSlot(s); const e = C.unitFromEnemy('rat', 100, 5, false, 'e0'); e.spd = 1; const B = C.create([P], [e], E.rng(2), {}); P.gauge = 100; heroTurn(B, P); P.mst = 12; C.act(B, P, { t: 'basic', tid: e.id }); B.ev.filter((q) => q.t === 'dmg').forEach((q) => assert(Number.isFinite(q.v) && q.v <= 9e12)); assert(/^\d/.test(E.fmtBig(d.maxHp))); });
t('нет бессмертия без цены: ни один навык/пассивка не даёт неуязвимость без расплаты', () => { const imm = Object.values(D.SKILLS).filter((k) => k.fx.some((f) => f.k === 'st' && f.id === 'immortal')); imm.forEach((k) => assert(k.hpCost > 0 && k.cd >= 99, k.id + ' бессмертие без цены/одно за бой')); assert(D.NODE_BY_ID.P33.e.m.secondLife); const s = mk(); s.hero.level = 100; s.hero.spent.P33 = 1; const P = C.unitFromSlot(s); const e = C.unitFromEnemy('rat', 100, 0, false, 'e0'); e.atk = 1e9; e.spd = 40; const B = C.create([P], [e], E.rng(2), {}); let g = 0; while (!B.over && g++ < 40) { const x = C.next(B); if (x === P) C.act(B, P, { t: 'basic', tid: e.id }); } assert(B.over === 'lose', 'вторая жизнь — только один раз'); });
t('имба-навыки доступны рано и сильны: ≥ 12 активных, множители ×2.8…×8.5, у каждого цена и КД', () => { const ks = Object.values(D.SKILLS).filter((k) => /^k_(wrath|rampage|titan|abyss|spear|unmake|edict|feast|chant|maw|flurry|bladestorm|oppress)$/.test(k.id)); assert.strictEqual(ks.length, 13); ks.forEach((k) => assert(k.mp && k.cd, k.id)); const mx = Math.max(...ks.map((k) => Math.max(...k.fx.filter((f) => f.k === 'dmg').map((f) => f.m * (f.hits && k.tgt !== 'rfoe' ? f.hits : 1), 0)))); assert(mx >= 8.5); const early = T.nodes.filter((n) => n.e.unlock && /^k_/.test(n.e.unlock) && n.lv <= 10 && D.SKILLS[n.e.unlock] && ks.includes(D.SKILLS[n.e.unlock])); assert(early.length >= 7, String(early.length)); });
t('миграция сохранения со старыми узлами дерева: прогресс R*/P*/D*/E*/V*/C* жив', () => { const s = mk(); s.hero.level = 30; s.hero.spent = { R1: 5, P1: 2, P14: 1, D2: 1, E5: 2, V4: 1, C2: 1 }; const p = S.migrate(JSON.parse(JSON.stringify({ v: 4, active: 0, slots: [s] }))); const sp = p.slots[0].hero.spent; assert.deepStrictEqual(sp, s.hero.spent); assert(E.skillsOf(p.slots[0].hero).includes('k_bolt')); });

